"""Load configuration from files and strings."""

import os

from miniconf.errors import ConfigError
from miniconf.parser import parse_lines

INCLUDE_DIRECTIVE = "@include"


def _read_lines(path):
    with open(path, "r", encoding="utf-8") as fh:
        return fh.read().splitlines()


def _expand(path, lines, stack):
    base_dir = os.path.dirname(os.path.abspath(path))
    expanded = []
    for raw in lines:
        tokens = raw.strip().split(None, 1)
        if not tokens or tokens[0] != INCLUDE_DIRECTIVE:
            expanded.append(raw)
            continue
        if len(tokens) < 2 or not tokens[1].strip():
            raise ConfigError("{}: @include requires a path".format(path))
        target = os.path.join(base_dir, tokens[1].strip())
        real = os.path.realpath(target)
        if real in stack:
            raise ConfigError("include cycle detected: {}".format(target))
        if not os.path.isfile(target):
            raise ConfigError("included file not found: {}".format(target))
        try:
            child_lines = _read_lines(target)
        except OSError as exc:
            raise ConfigError(
                "cannot read included file {}: {}".format(target, exc)
            ) from exc
        stack.add(real)
        try:
            expanded.extend(_expand(target, child_lines, stack))
        finally:
            stack.discard(real)
    return expanded


def load(path):
    """Read and parse the configuration file at ``path``.

    ``@include <path>`` lines are replaced in place by the contents of the
    referenced file, resolved relative to the including file's directory.
    """
    lines = _read_lines(path)
    lines = _expand(path, lines, {os.path.realpath(path)})
    return parse_lines(lines)


def loads(text):
    """Parse configuration from a string."""
    return parse_lines(text.splitlines())
